// STEP 1 — STRATEGY SELECTION
const input = $input.first().json.body || $input.first().json;

const { current_location, fuel_level, orders = [], new_order } = input;

let selected_mode = "Balanced Mode";
let mode_reason = "";

if (new_order && new_order.priority === "high") {
  selected_mode = "Emergency Mode";
  mode_reason = `New order #${new_order.id} has high priority — activating Emergency Mode to handle it immediately.`;
} else if (fuel_level < 30) {
  selected_mode = "Cost Mode";
  mode_reason = `Fuel level is critically low at ${fuel_level}% (below 30%) — activating Cost Mode to minimize travel distance and conserve fuel.`;
} else {
  const highPriorityCount = orders.filter(o => o.priority === "high").length;
  const totalOrders = orders.length;
  if (totalOrders > 0 && highPriorityCount / totalOrders > 0.5) {
    selected_mode = "Speed Mode";
    mode_reason = `${highPriorityCount} of ${totalOrders} orders (${Math.round(highPriorityCount/totalOrders*100)}%) are high priority — activating Speed Mode.`;
  } else {
    selected_mode = "Balanced Mode";
    mode_reason = `No emergency, fuel is adequate (${fuel_level}%), and high priority orders are not dominant — using Balanced Mode for optimal efficiency.`;
  }
}

return [{
  json: {
    ...input,
    selected_mode,
    mode_reason
  }
}];

// STEP 2 — ROUTE OPTIMIZATION
const data = $input.first().json;
const { current_location, orders = [], new_order, selected_mode } = data;

function haversineDistance(coord1, coord2) {
  const R = 6371; // Earth radius km
  const toRad = deg => deg * Math.PI / 180;
  const dLat = toRad(coord2[0] - coord1[0]);
  const dLon = toRad(coord2[1] - coord1[1]);
  const a = Math.sin(dLat/2)**2 +
            Math.cos(toRad(coord1[0])) * Math.cos(toRad(coord2[0])) *
            Math.sin(dLon/2)**2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
}

function calcTotalDistance(sequence, startCoord) {
  let total = 0;
  let prev = startCoord;
  for (const order of sequence) {
    total += haversineDistance(prev, order.location);
    prev = order.location;
  }
  return Math.round(total * 10) / 10;
}

function greedyNearest(remaining, start) {
  const route = [];
  let current = start;
  let pool = [...remaining];
  while (pool.length > 0) {
    pool.sort((a, b) => haversineDistance(current, a.location) - haversineDistance(current, b.location));
    const next = pool.shift();
    route.push(next);
    current = next.location;
  }
  return route;
}

const priorityWeight = { high: 3, medium: 2, low: 1 };

let allOrders = [...orders];
if (new_order) allOrders.push(new_order);

let optimized_route = [];
let optimization_explanation = "";

if (allOrders.length === 0) {
  optimized_route = [];
  optimization_explanation = "No orders to route. Vehicle is idle.";
} else if (selected_mode === "Emergency Mode" && new_order) {
  const emergency = allOrders.find(o => o.id === new_order.id);
  const rest = allOrders.filter(o => o.id !== new_order.id);
  const restRouted = greedyNearest(rest, new_order.location);
  optimized_route = [emergency, ...restRouted].map(o => o.id);
  optimization_explanation = `Emergency order #${new_order.id} dispatched first. Remaining ${rest.length} orders optimized by proximity from emergency drop-off point.`;
} else if (selected_mode === "Speed Mode") {
  const highOrders = allOrders.filter(o => o.priority === "high");
  const others = allOrders.filter(o => o.priority !== "high");
  const highRouted = greedyNearest(highOrders, current_location);
  const lastHigh = highRouted.length > 0 ? highRouted[highRouted.length - 1].location : current_location;
  const otherRouted = greedyNearest(others, lastHigh);
  optimized_route = [...highRouted, ...otherRouted].map(o => o.id);
  optimization_explanation = `Speed Mode: ${highOrders.length} high-priority orders dispatched first via nearest-neighbor, then ${others.length} remaining orders optimized by distance.`;
} else if (selected_mode === "Cost Mode") {
  const routed = greedyNearest(allOrders, current_location);
  optimized_route = routed.map(o => o.id);
  optimization_explanation = `Cost Mode: All ${allOrders.length} orders routed using nearest-neighbor algorithm to minimize total travel distance and fuel consumption.`;
} else {
  // Balanced Mode — weighted score of distance and priority
  const route = [];
  let remaining = [...allOrders];
  let current = current_location;
  while (remaining.length > 0) {
    const maxDist = Math.max(...remaining.map(o => haversineDistance(current, o.location))) || 1;
    remaining.sort((a, b) => {
      const distA = haversineDistance(current, a.location) / maxDist;
      const distB = haversineDistance(current, b.location) / maxDist;
      const scoreA = distA - (priorityWeight[a.priority] * 0.3);
      const scoreB = distB - (priorityWeight[b.priority] * 0.3);
      return scoreA - scoreB;
    });
    const next = remaining.shift();
    route.push(next);
    current = next.location;
  }
  optimized_route = route.map(o => o.id);
  optimization_explanation = `Balanced Mode: Orders scored using weighted combination of proximity (70%) and priority (30%). ${allOrders.length} orders sequenced for optimal efficiency.`;
}

const orderedObjects = optimized_route.map(id => allOrders.find(o => o.id === id)).filter(Boolean);
const estimated_total_distance = calcTotalDistance(orderedObjects, current_location);

return [{
  json: {
    ...data,
    optimized_route,
    estimated_total_distance,
    optimization_explanation
  }
}];

// STEP 3 — RISK ASSESSMENT
const data = $input.first().json;
const { fuel_level, orders = [], new_order, estimated_total_distance, selected_mode, optimized_route } = data;

const allOrders = new_order ? [...orders, new_order] : [...orders];
const risk_factors = [];

// Fuel risk
const estimatedFuelNeeded = estimated_total_distance * 0.08; // assume 8% fuel per 100km baseline
if (fuel_level < 15) {
  risk_factors.push(`CRITICAL: Fuel at ${fuel_level}% — vehicle may not complete route (estimated ${estimated_total_distance} km needed).`);
} else if (fuel_level < 30) {
  risk_factors.push(`LOW FUEL: ${fuel_level}% remaining — refueling stop recommended before or during route.`);
} else if (fuel_level < 50 && estimated_total_distance > 150) {
  risk_factors.push(`Moderate fuel concern: ${fuel_level}% fuel for a ${estimated_total_distance} km route — monitor levels.`);
}

// Long detour risk
if (estimated_total_distance > 200) {
  risk_factors.push(`Long route detected: ${estimated_total_distance} km total — potential driver fatigue and delivery time risk.`);
}

// Low priority delay risk
const lowPriorityOrders = allOrders.filter(o => o.priority === "low");
if (lowPriorityOrders.length > 0 && (selected_mode === "Speed Mode" || selected_mode === "Emergency Mode")) {
  risk_factors.push(`${lowPriorityOrders.length} low-priority order(s) may face significant delays due to ${selected_mode}.`);
}

// No orders risk
if (allOrders.length === 0) {
  risk_factors.push("No active orders — pipeline may have upstream data issues.");
}

// Operational inefficiency
if (selected_mode === "Cost Mode" && allOrders.some(o => o.priority === "high")) {
  risk_factors.push("Cost Mode active with high-priority orders present — SLA breach risk for time-sensitive deliveries.");
}

// Determine risk level
let risk_level = "Low";
const criticalFactors = risk_factors.filter(f => f.startsWith("CRITICAL"));
const warnFactors = risk_factors.filter(f => !f.startsWith("CRITICAL"));

if (criticalFactors.length > 0 || risk_factors.length >= 3) {
  risk_level = "High";
} else if (warnFactors.length >= 2 || (fuel_level < 30 && estimated_total_distance > 100)) {
  risk_level = "Medium";
} else {
  risk_level = "Low";
}

const risk_explanation = risk_factors.length === 0
  ? `All systems nominal. Fuel is adequate at ${fuel_level}%, route distance is manageable at ${estimated_total_distance} km, and no priority conflicts detected.`
  : `${risk_level} operational risk identified based on ${risk_factors.length} factor(s): fuel sufficiency, route length, and priority-delivery conflicts.`;

return [{
  json: {
    ...data,
    risk_level,
    risk_factors,
    risk_explanation
  }
}];

// FINAL RESPONSE BUILDER
const data = $input.first().json;

const final_summary = `[${data.selected_mode}] Vehicle at (${data.current_location}) with ${data.fuel_level}% fuel. ` +
  `${data.optimized_route.length} orders sequenced over ${data.estimated_total_distance} km. ` +
  `Risk: ${data.risk_level}. ${data.risk_factors.length > 0 ? data.risk_factors[0] : 'All clear.'}`;

const response = {
  mode: data.selected_mode,
  route: data.optimized_route,
  distance: data.estimated_total_distance,
  mode_reason: data.mode_reason,
  optimization_explanation: data.optimization_explanation,
  risk_level: data.risk_level,
  risk_factors: data.risk_factors,
  final_summary
};

return [{ json: response }];
